#!/usr/bin/env python3
"""Create v2 of a narrowly scoped 2020 source-only temperature pilot."""
import csv,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];P=R/'proposals/restored_source_only_2020_march_outtemp_v2';P.mkdir(parents=True,exist_ok=True)
old=json.loads((R/'proposals/restored_source_only_2020_march_outtemp/source_snapshot.json').read_text())
oldrefs=json.loads((R/'proposals/restored_source_only_2020_march_outtemp/regional_context_snapshot.json').read_text())
oldlocal=json.loads((R/'proposals/restored_source_only_2020_march_outtemp/local_target_state.json').read_text())
review=json.loads((R/'data/source_only_strict_2013_2020_review.json').read_text())
remaining={int(r['ts']):r for r in json.loads((R/'data/source_only_remaining_strict_copy_cohorts.json').read_text())['records']}
# Current read-only source row/neighbor observations captured 2026-11-14.
newinfo={1582118400:{'utc':'2020-02-19T13:20:00Z','value':8.31666666666667,'prev':8.41666666666667,'next':8.13333333333333,'local':{'target_exists':False,'change_events':0,'nearest_before':{'dateTime':1582104300,'outTemp':None},'nearest_after':{'dateTime':1582122300,'outTemp':None}},'ref':{'n_1h':25,'exact_n':1,'temperature_min_c':8.3,'temperature_max_c':8.8,'temperature_mean_c':8.532,'temperature_exact_c':8.7,'rh_min':52,'rh_max':55,'rh_mean':53.88,'rh_exact':53}},1583059200:{'utc':'2020-03-01T10:40:00Z','value':6.4,'prev':6.5,'next':6.5,'local':{'target_exists':False,'change_events':0,'nearest_before':{'dateTime':1583044200,'outTemp':2.7},'nearest_after':{'dateTime':1583069100,'outTemp':7.8}},'ref':{'n_1h':25,'exact_n':1,'temperature_min_c':7.5,'temperature_max_c':7.9,'temperature_mean_c':7.688,'temperature_exact_c':7.7,'rh_min':66,'rh_max':68,'rh_mean':67.36,'rh_exact':68}}}
old_by={int(x['timestamp']):x for x in old};oldref_by={int(x['timestamp']):x for x in oldrefs};oldlocal_by={int(k):v for k,v in oldlocal.items()}
source=[];regions=[];locals_=[];metadata=[];ops=[]
for t in [1582118400,1583059200,1583078400,1583097600]:
 if t in old_by:
  s=old_by[t];m=next(x for x in json.loads((R/'proposals/restored_source_only_2020_march_outtemp/candidate_metadata.json').read_text()) if x['timestamp']==t); reg=oldref_by[t]; loc=oldlocal_by[t]
  source.append(s);regions.append(reg);locals_.append({'timestamp':t,**loc});metadata.append(m)
  ops.append(next(o for o in json.loads((R/'proposals/restored_source_only_2020_march_outtemp/corrections.json').read_text()) if o['timestamp']==t))
  reason=f"RESTORED; MODERATE provenance. Exact 5-minute outTemp source value is present and identical in old_weewx and weewx_WH1080; copies are dependent, not independent sensors. usUnits=17/interval=5. The target row is absent from reconstruction, current EU, GW1000 and eu_old, while old_weewx and WH1080 hold the source row; target change events are zero. Source temperature is smooth across adjacent source rows and the 25-row LuhaMet temperature context is coherent. For {s['utc']}, local surrounding temperature context is as recorded in the package; at 21:20 local rows bracket 5.4 C with 5.3 C. Uncertainty: exact historical archive origin and reason for target omission are unknown. At the same two timestamps source RH (11%,31%) conflicts sharply with local/reference context and remains REVIEW_REQUIRED; possible prior row omission due RH cannot be excluded. Restore outTemp only, with no other field synthesized."
 else:
  q=newinfo[t];r=remaining[t]
  assert r['old_temp']==q['value'] and r['old_units']==17 and r['old_interval']==5 and r['change_events']==0
  src={'timestamp':t,'utc':q['utc'],'source_databases':['old_weewx','weewx_WH1080'],'source_concordance':'Current READ-ONLY query: exact outTemp matches at target and both adjacent 5-minute source timestamps; archives are dependent copies.','usUnits':17,'interval':5,'source_values':{'outTemp':q['value'],'outHumidity':r['old_rh'],'rain':r['old_rain'],'rainRate':r['old_rainRate'],'windSpeed':r['old_wind']},'archive_row_presence_by_database':{'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':False,'old_weewx':True,'weewx_WH1080':True},'change_events':0,'source_context_5min':{'before':{'dateTime':t-300,'outTemp':q['prev']},'exact':{'dateTime':t,'outTemp':q['value']},'after':{'dateTime':t+300,'outTemp':q['next']}},'regional_window':q['ref'],'live_reconstruction_neighbors':q['local']}
  source.append(src);regions.append({'timestamp':t,**q['ref'],'source':'READ_ONLY aggregate of LuhaMet reference_only, 5-minute samples in ±3600 seconds; SQL included.'});locals_.append({'timestamp':t,**q['local']})
  m={'timestamp':t,'utc':q['utc'],'classification':'RESTORED','confidence':'MODERATE','operation':'insert outTemp only','source_archive':'old_weewx; exact outTemp also in weewx_WH1080; dependent copies','source_value':q['value'],'usUnits':17,'interval_minutes':5,'target_expected_state':'No target archive row at exact timestamp in frozen six-archive evidence; current reconstruction exact-target query also absent; no change event.','outTemp_evidence':'Exact source-copy value; adjacent source temperatures differ by <0.2 C; exact 5-minute LuhaMet observation plus a 25-row ±60-minute window; local reconstruction has no outTemp at target.','context_field_flags':{'outHumidity':'NULL in both source rows; no proposal','rain':'source zero only; excluded','rainRate':'source zero only; excluded','windSpeed':'not field-validated for restoration; excluded'},'uncertainty':'MODERATE provenance. Archive origin and historical omission rationale unknown; regional station does not establish local truth; no individual interval applies.','approval':'NOT_APPROVED','actual_mcp_dry_run':'NOT_RUN','application':'NOT_APPLIED'}
  metadata.append(m)
  reason=f"RESTORED; MODERATE provenance. Exact source outTemp {q['value']} C at {q['utc']} is present in old_weewx and weewx_WH1080 with usUnits=17, interval=5; source copies are dependent, not independent sensors. Current READ-ONLY queries confirm the target source rows and matching outTemp at both adjacent five-minute source times ({q['prev']} and {q['next']} C); target archive row is absent in frozen six-archive evidence and reconstruction change history has zero events. LuhaMet has an exact-time reference ({q['ref']['temperature_exact_c']} C) and 25 five-minute samples in ±1 hour (range {q['ref']['temperature_min_c']}–{q['ref']['temperature_max_c']} C), supporting temperature plausibility. Uncertainty: exact historic archive origin and reason for target omission are unknown; two archive copies may share lineage and regional observation is not local truth. This restores only the source outTemp measurement; rain/rainRate zero and other fields are excluded."
  ops.append({'operation':'insert','timestamp':t,'variable':'outTemp','new_value':q['value'],'expected_old_value':None,'source_database':'old_weewx','source_time':t,'source_value':q['value'],'reason':reason,'us_units':17,'interval_minutes':5})
# Existing two operations were carried forward above from the immutable v1 snapshot.
ops.sort(key=lambda o:o['timestamp']);source.sort(key=lambda x:x['timestamp']);regions.sort(key=lambda x:x['timestamp']);locals_.sort(key=lambda x:x['timestamp']);metadata.sort(key=lambda x:x['timestamp'])
assert len(ops)==len(source)==len(regions)==len(locals_)==len(metadata)==4

def wj(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
wj('corrections.json',ops);wj('source_snapshot.json',source);wj('regional_context_snapshot.json',regions);wj('local_target_state.json',locals_);wj('candidate_metadata.json',metadata)
with (P/'corrections.csv').open('w',newline='') as f:
 c=csv.DictWriter(f,fieldnames=list(ops[0]));c.writeheader();c.writerows(ops)
# A local, non-targeted strict concordance case is retained as a reasoned exclusion.
ex=[{'timestamp':1582368000,'utc':'2020-02-22T10:40:00Z','variable':'outTemp','status':'REVIEW_REQUIRED_EXCLUDED','source_value_c':8.2,'local_before_c':5.8,'local_after_c':6.3,'luhamet_exact_c':7.2,'reason':'Source value differs by 1.9–2.4 C from the nearest local reconstruction values; despite source-copy agreement and regional plausibility, local-source conflict prevents restoration.'}]
with (P/'excluded_cases.csv').open('w',newline='') as f:
 c=csv.DictWriter(f,fieldnames=list(ex[0]));c.writeheader();c.writerows(ex)
(P/'sql_readonly_context.sql').write_text('''-- READ-ONLY exact source and local reference evidence for candidate timestamps.\nSELECT dateTime,usUnits,`interval`,outTemp,outHumidity,rain,rainRate,windSpeed FROM archive WHERE dateTime IN (1582118100,1582118400,1582118700,1582367700,1582368000,1582368300,1583058900,1583059200,1583059500,1583078100,1583078400,1583078700,1583097300,1583097600,1583097900) ORDER BY dateTime;\nSELECT target.ts,r.observed_at_utc,r.temperature_c,r.relative_humidity_pct FROM (SELECT 1582118400 ts UNION ALL SELECT 1582368000 UNION ALL SELECT 1583059200 UNION ALL SELECT 1583078400 UNION ALL SELECT 1583097600) target LEFT JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=target.ts AND r.quality_status='reference_only' AND r.source_resolution='5min' ORDER BY target.ts;\n-- Run each archive-specific source query only against named READ-ONLY Weather MCP databases.\n''')
(P/'simulate.py').write_text('''#!/usr/bin/env python3\nimport json\nfrom pathlib import Path\np=Path(__file__).resolve().parent;o=json.loads((p/'corrections.json').read_text())\nprint(json.dumps({'simulation':'local in-memory proposal accounting only','operations':len(o),'physical_insert_rows':len({x['timestamp'] for x in o if x['operation']=='insert'}),'updates':0,'batches':1,'max_batch_size':len(o),'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'},indent=2))\n''')
(P/'validate.py').write_text('''#!/usr/bin/env python3\nimport json,hashlib\nfrom pathlib import Path\np=Path(__file__).resolve().parent;ops=json.loads((p/'corrections.json').read_text());src=json.loads((p/'source_snapshot.json').read_text());meta=json.loads((p/'candidate_metadata.json').read_text());refs=json.loads((p/'regional_context_snapshot.json').read_text());loc=json.loads((p/'local_target_state.json').read_text());man=json.loads((p/'manifest.json').read_text())\nassert len(ops)==len(src)==len(meta)==len(refs)==len(loc)==4 and len({x['timestamp'] for x in ops})==4\nfor o,s,m,r,l in zip(ops,src,meta,refs,loc):\n assert o['operation']=='insert' and o['variable']=='outTemp' and o['expected_old_value'] is None and o['new_value']==o['source_value']==s['source_values']['outTemp']==m['source_value']\n assert 'RESTORED' in o['reason'] and 'MODERATE provenance' in o['reason'] and 'Uncertainty:' in o['reason']\n assert s['usUnits']==17 and s['interval']==5 and s['change_events']==0 and s['source_databases']==['old_weewx','weewx_WH1080'] if 'source_databases' in s else s['usUnits']==17 and s['interval']==5 and s['change_events']==0\n assert s['archive_row_presence_by_database']=={'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':False,'old_weewx':True,'weewx_WH1080':True}\n assert m['classification']=='RESTORED' and m['confidence']=='MODERATE' and m['approval']=='NOT_APPROVED' and m['actual_mcp_dry_run']=='NOT_RUN' and m['application']=='NOT_APPLIED'\n assert (len(r['rows'])==25 if 'rows' in r else r['n_1h']==25 and r['exact_n']==1)\n assert l['target_exists'] is False\nassert [x['timestamp'] for x in ops]==[1582118400,1583059200,1583078400,1583097600]\nfor x in man['files']:\n b=(p/x['path']).read_bytes();assert len(b)==x['bytes'] and hashlib.sha256(b).hexdigest()==x['sha256'],x['path']\nprint('PASS: four RESTORED/MODERATE outTemp proposals, per-archive state, source continuity, reference and local context, case exclusion, manifest; no writes.')\n''')
(P/'README.md').write_text('''# 2020 March source-only outTemp pilot v2\n\nFour target timestamps: 2020-02-19 13:20, 2020-03-01 10:40, 2020-03-01 16:00 and 21:20 UTC. Exact 5-minute outTemp values from old_weewx match weewx_WH1080 at all four timestamps; the copies are treated as dependent archives. Current SELECT-only source/reconstruction checks, frozen per-archive availability and historical change evidence are preserved. Local and regional reference context is field-specific.\n\nThe 2020-02-22 10:40 candidate (8.2 C) is excluded REVIEW_REQUIRED because local reconstruction neighbors are 5.8 and 6.3 C, despite a plausible 7.2 C LuhaMet value. RH-conflicted values at 16:00/21:20 remain excluded; only outTemp is proposed. Exact archive provenance and historical omission intent remain unknown: RESTORED/MODERATE is a draft classification, not approval.\n\nRun `python3 validate.py` and `python3 simulate.py` from this directory. Local simulation only; no database writes, staging, MCP dry-run or application.\n''')
# Manifest
files=sorted(x.name for x in P.iterdir() if x.is_file() and x.name!='manifest.json')
(P/'manifest.json').write_text(json.dumps({'schema':'proposal-manifest-v1','package':'restored-source-only-2020-march-outtemp','version':'v2','supersedes':'proposals/restored_source_only_2020_march_outtemp','classification':'RESTORED','confidence':'MODERATE','operation_count':4,'excluded_cases':1,'files':[{'path':f,'bytes':(P/f).stat().st_size,'sha256':hashlib.sha256((P/f).read_bytes()).hexdigest()} for f in files]},indent=2)+'\n')
print('built',len(files)+1,'files')
